import Link from 'next/link'
import ArticleBody from '@/components/blog/ArticleBody'
import { getPublishedPolicy, POLICY_PAGES, type PolicyPageKind } from '@/lib/legal/publication'

/**
 * Public policy content is supplied through the audited administrator article
 * editor, never generated by the application or inferred from its code.
 */
export default async function PublishedPolicyPage({ kind }: { kind: PolicyPageKind }) {
  const policy = await getPublishedPolicy(kind)
  const title = POLICY_PAGES[kind].title
  return (
    <div className="container mx-auto max-w-4xl space-y-8 px-4 py-12">
      <nav aria-label="Breadcrumb" className="text-sm text-muted-foreground">
        <Link href="/" className="hover:underline">Home</Link>
        <span aria-hidden="true" className="mx-2">/</span>
        <span aria-current="page">{title}</span>
      </nav>
      {policy ? (
        <article className="space-y-6 rounded-xl border bg-white p-6 shadow-sm sm:p-10">
          <div className="space-y-2">
            <h1 className="text-3xl font-bold text-slate-950">{title}</h1>
            <p className="text-sm text-slate-600">
              Last updated <time dateTime={policy.updatedAt.toISOString()}>{policy.updatedAt.toLocaleDateString('en-IN')}</time>
            </p>
          </div>
          <ArticleBody content={policy.content} />
        </article>
      ) : (
        <section aria-labelledby="policy-not-ready" className="space-y-5 rounded-xl border border-amber-300 bg-amber-50 p-6 sm:p-10">
          <h1 id="policy-not-ready" className="text-3xl font-bold text-slate-950">{title} is not published yet</h1>
          <p className="text-sm leading-7 text-slate-900">
            The finalized {title.toLowerCase()} has not been made available by the platform administrator.
            This notice is not a policy or a legal agreement. A public commercial launch must not be approved
            until the correct policy is reviewed and published.
          </p>
          <p className="text-sm leading-7 text-slate-900">
            For questions about your existing account, booking or purchase, use the Help Center or send a private support request.
          </p>
          <div className="flex flex-wrap gap-3">
            <Link href="/help" className="rounded-lg border border-amber-500 px-4 py-2 text-sm font-semibold text-slate-950 hover:bg-amber-100">Help Center</Link>
            <Link href="/dashboard/support" className="rounded-lg bg-slate-900 px-4 py-2 text-sm font-semibold text-white hover:bg-slate-800">Contact support</Link>
          </div>
        </section>
      )}
    </div>
  )
}
